import com.evolveum.midpoint.xml.ns._public.common.common_3.*

// Recompute the catalog orgs + role so their parentOrgRef /
// membership (the hierarchy the catalog tree renders) is
// projected — a plain import doesn't always compute it. Idempotent.
for (oid in ['c5e10000-0000-0000-0000-000000000001',
             'c5e10000-0000-0000-0000-000000000002',
             'c5e10000-0000-0000-0000-000000000003']) {
    midpoint.recompute(OrgType.class, oid)
}
midpoint.recompute(RoleType.class, 'c5cccccc-cccc-cccc-cccc-cccccccccccc')
midpoint.recompute(RoleType.class, 'c5eeeeee-eeee-eeee-eeee-eeeeeeeeeeee')

// Point the self-service role catalog at the Catalog Root org.
rootRef = new ObjectReferenceType()
rootRef.setOid('c5e10000-0000-0000-0000-000000000001')
rootRef.setType(OrgType.COMPLEX_TYPE)
delta = midpoint.deltaFor(SystemConfigurationType.class)
    .item(SystemConfigurationType.F_ROLE_MANAGEMENT, RoleManagementConfigurationType.F_ROLE_CATALOG_REF)
    .replace(rootRef.asReferenceValue())
    .asObjectDeltas('00000000-0000-0000-0000-000000000001')
midpoint.modifyObject(delta)
log.info("IDWEAVE: role catalog root set + catalog orgs recomputed")
